scripts.岳云对话.txt:
// 和岳云对话

	If ($Event == 430) @Event430;
	If ($Event == 440) @Event440;
	If ($Event == 450) @Event450;
	If ($Event == 695) @Event695;

	If ($Talkliang == 0) @Eventliang0;
	If ($Talkliang == 3) @Eventliang3;		// 这时 $Talkyueyun 只可能为 0
	
@Eventliang0:
	If ($Talkyueyun == 0) @Talkyueyun0;
	If ($Talkyueyun == 1) @Talkyueyun1;
	
 @Talkyueyun0:	
	Say("岳云：我是岳云，两位有什么事？", 62);
	Say("独孤剑：在下独孤剑。我们有要是拜见岳飞元帅。事情是这样的……", 1);
	FadeOut();
	Sleep(500);
	FadeIn();
	Say("岳云：岂有此理，好歹毒的金狗！我岳云决不会放过他们。", 62);
	Say("独孤剑：岳将军，请提醒岳元帅务必小心。我们先告辞了！", 1);
	Say("岳云：独孤兄弟，张姑娘，多谢你们。父帅明日回营，我想请两位见见父帅如何？大宋就需要像两位这样的豪杰之士，今后我们若能在沙场并肩杀敌，那才是人生快事！", 62);
	Say("独孤剑：岳将军果然是豪气干云！若能和将军并力戮敌，驱除鞑虏，收复我大好河山，独孤剑不枉此生。好，明日我定当前来拜见岳元帅！", 2);
	Say("张琳心：还有我呢！我也要像梁夫人和穆桂英一样，巾帼胜须眉！", 23);
	Say("独孤剑：那我们先告辞了！", 2);
	Say("岳云：两位慢走，岳云明日在此恭候！", 62);
	Memo("来到岳飞大营，岳飞不在，两人将血书交给了岳云。");
	DelGoods("Goods401_血书.ini");
	Assign($Talkyueyun, 1);
	Return;
	
 @Talkyueyun1:
	Say("岳云：多谢两位，我一定将“血书”亲手交给父帅。", 62);
	Return;

	
@Eventliang3:
	Say("岳云：我是岳云，两位有什么事？", 62);
	Say("独孤剑：在下独孤剑。我们有要是拜见岳飞元帅。事情是这样的……", 1);
	FadeOut();
	Sleep(500);
	FadeIn();
	Say("岳云：岂有此理，好歹毒的金狗！我岳云决不会放过他们。", 62);
	Say("独孤剑：岳将军，请提醒岳元帅务必小心。我们先告辞了！", 1);
	Say("岳云：独孤兄弟，张姑娘，多谢你们。父帅明日回营，我想请两位见见父帅如何？大宋就需要像两位这样的豪杰之士，今后我们若能在沙场并肩杀敌，那才是人生快事！", 62);
	Say("独孤剑：岳将军果然是豪气干云！若能和将军并力戮敌，驱除鞑虏，收复我大好河山，独孤剑不枉此生。好，明日我定当前来拜见岳元帅！", 2);
	Say("张琳心：还有我呢！我也要像梁夫人和穆桂英一样，巾帼胜须眉！", 23);
	Say("独孤剑：那我们先告辞了！", 2);
	Say("岳云：两位慢走，岳云明日在此恭候！", 62);
	Memo("来到岳飞大营，岳飞不在，两人将血书交给了岳云。");
	DelGoods("Goods401_血书.ini");
	Assign($Talkyueyun, 1);
	Assign($Event, 430);
	Return;
	
@Event430:
	Say("岳云：多谢两位，我一定将“血书”亲手交给父帅。", 62);
	Return;
	
@Event440:
	Say("岳云：独孤兄弟和张姑娘来啦？父帅正等着二位呢，你们有什么事就和父帅说吧。", 62);
	Return;		
	
@Event450:
	Say("岳云：我倒想和那个陆文龙较量一下。", 62);
	Return;
	
@Event695:
	Say("岳云：是独孤大哥！你的伤好了——上次可辛苦张姑娘了。", 62);
	Say("独孤剑：岳将军，元帅呢？", 1);
	Say("岳云：今天“心剑客”方大侠送来了“山河社稷图”，父帅和方大侠去凤凰山勘查地形去了……", 62);
	Say("独孤剑：糟了！元帅危险！", 6);
	Say("岳云：怎么了……", 62);
	Say("独孤剑：方勉便是五色教的教主，这次他想借献图谋害岳元帅！", 9);
	Say("岳云：什么？那我们即刻去救父帅！", 62);
	Say("独孤剑：将军赶快调集人手，我和琳儿先行赶去！", 9);
	Say("岳云：好！拜托大哥了！", 62);
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	SetNpcDeathScript("张琳心", "主角死亡.txt");
	StopMusic();
	PlayMusic("追缘.mp3");
	SetPlayerDir(7);
	SetNpcDir("张琳心",7);
	NpcGoto("岳云",9,26);
	DelNpc("岳云");
	
	SetTimeScript(0, "岳飞死亡.txt");
	OpenTimeLimit(60);
	Assign($Event, 700);
	Memo("见过岳云，方知方勉已先一步引岳飞到凤凰山。时间紧迫，独孤剑和张琳心决定先行赶去营救。");
	Return;

scripts.岳飞对话.txt:
// 与岳飞的对话

	If ($Event == 440) @Event440;
	If ($Event == 450) @Event450;
	
@Event440:
	Say("岳飞：多谢二位少侠前来传信，如果江湖义士都能像两位一样与我大宋将士同仇敌忾，那我大军直捣黄龙，便指日可待了。", 58);
	Say("独孤剑：元帅似乎为什么事而烦恼，在下可有效劳之处？", 1);
	Say("岳飞：昨日阵前来了个叫陆文龙的金将，骁勇无比，连败我几员大将，令我军士气大挫。", 58);
	Say("张琳心：这陆文龙果真如此了得？", 21);
	Say("岳飞：本帅恼的倒不是那陆文龙。纵他武艺如何高强，本帅总有计谋除他。我担心的是王佐将军。他自断一臂去金营诈降，要劝说那陆文龙归降。此去凶险重重，让人担忧。", 58);
	Say("独孤剑：原来如此。王将军大智大勇，实在让人钦佩。如蒙元帅不弃，在下愿往金营走一遭，打探王将军的消息。", 1);
	Say("岳飞：这太危险，万万不可。", 58);
	Say("独孤剑：岳帅，在下自幼身在江湖，但也知忠义大节。我大宋遭强虏欺凌，我辈早有报国之心，只恨效力无门。此去金营，正有用得着我江湖中人身手的地方，谅寻常金兵也拿我无可奈何。万望岳帅准行。", 1);
	Say("岳飞：这个……", 58);
	Watch("独孤剑", "张琳心", 0);
	Say("张琳心：我也去。", 21);
	Say("独孤剑：琳儿，你留下来。", 1);
	Say("张琳心：为什么？如果你此去凶险重重，那我就恳求岳元帅不许你去；如果此去并无危险，我去如何使不得？", 27);
	Say("岳飞：我看此事还是太危险，岳某不能让两位冒险。", 58);
	Watch("岳飞", "独孤剑", 0);
	Say("独孤剑：元帅！", 1);
	Say("张琳心：岳元帅，不如我们化装成金兵的模样混入，不就万无一失了吗？", 21);
	Say("独孤剑：这倒是一个好办法！", 2);
	Say("岳飞：嗯……好吧。不过你们千万要小心，一有危险速速撤回。", 58);
	Say("独孤剑：多谢元帅！", 2);
	Say("岳飞：这是两套金兵的衣服，金营守卫森严，如果你们从两军对阵的战场直接过去恐怕凶多吉少，一个人武功再高，面对千军万马也是无法抵挡。你们可从西边的凤凰山绕到金兵大营后面，等天黑后换上金服再混进金营，方为上策。", 58);
	Say("独孤剑：元帅放心，我们一定不辱使命！", 1);
	AddGoods("Goods408_金服.ini");
	AddGoods("Goods408_金服.ini");
	Assign($Event, 450);
	SetMapTrap(1, "trap01.txt");
	Memo("来到岳飞大营，见到岳飞。二人得知金兀术的养子陆文龙连败数名宋军大将，于是自告奋勇前去金营打探。岳飞送给独孤剑和张琳心两件金服作为伪装。");
	Return;
	
@Event450:
	Say("岳飞：出了营门往西走就是凤凰山，两位要多加小心！", 58);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的对话

	If ($Event << 430) @Eventless430;
	If ($Event == 430) @Event430;			//两个军营都已去过
	If ($Event == 440) @Event440;
	If ($Event == 450) @Event450;
	If ($Event == 695) @Event695;
	If ($Event == 700) @Event700;
	
@Eventless430:	
	If ($Talkyueyun == 0) @Eventyueyun0;	//尚未见到岳云
	If ($Talkyueyun == 1) @Eventyueyun1;	//已经见到岳云
@Eventyueyun0:
	Say("张琳心：那个少年将军应该就是岳云吧。", 21);
	Return;		
@Eventyueyun1:	
	Say("张琳心：我们去韩世忠大营吧。", 21);
	Return;	
	
@Event430:
	Say("张琳心：我们明天再来吧！", 21);
	Return;	
	
@Event440:
	Say("独孤剑：我从小就十分崇拜岳飞元帅，今天能见到他，真是三生有幸！", 2);
	Return;	
	
@Event450:
	Say("独孤剑：琳儿，此行艰险万分，你还是留在这里等我吧！", 1);
	Say("张琳心：独孤哥哥，如果你一个人去，你叫我怎么放得下心呢？那比死还难受！要死，我们也要死在一起！", 21);
	Say("独孤剑：琳儿！…… 好！我们一起去！", 2);
	Return;
	
@Event695:
	Say("张琳心：独孤哥哥，那不是岳云将军吗？",21);
	Return;
	
@Event700:	
	Say("张琳心：独孤哥哥，我们赶快去凤凰山吧，晚了就来不及了！", 21);
	Return;

